{"read_file": "import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_WEIGHTS = {
    "miner_3_20280113_relative_reversal_3d": 0.35,
    "miner_3_20280127_dispersion_relative_reversal_3d": 0.15,
    "miner_3_clv_1d": 0.15,
    "peer_median_leadlag_5d": 0.15,
    "miner_2_risk_adjusted_momentum_20d": 0.10,
    "miner_2_20280127_volscaled_trend_10d": 0.10,
}
DIRECTIONS = {k: 1 for k in FACTOR_WEIGHTS}
MIN_W, MAX_W, REBALANCE_DAYS = 0.015, 0.16, 10
last_date = None


def rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def bounded(raw):
    # Box-constrained simplex projection, retaining a small allocation in every asset.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    w = {s: x / z for s, x in w.items()}
    for _ in range(100):
        low = [s for s in UNIVERSE if w[s] < MIN_W]
        high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high:
            break
        for s in low: w[s] = MIN_W
        for s in high: w[s] = MAX_W
        fixed = set(low + high)
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        if not free: break
        q = sum(w[s] for s in free) or 1.0
        for s in free: w[s] = rem * w[s] / q
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_date
    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=100)
        if df is None or len(df) < 65: continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        market[s] = (c, h, l, r, str(df.iloc[-1]["date"]))
    if len(market) < 12: return
    decision = max(x[4] for x in market.values())
    if last_date is not None:
        try:
            if (np.datetime64(decision, "D") - np.datetime64(last_date, "D")) / np.timedelta64(1, "D") < REBALANCE_DAYS: return
        except Exception: return

    relative, dispersion_relative, clv, five, momentum, trend, invvol = {}, {}, {}, {}, {}, {}, {}
    # Cross-sectional trailing dispersion history, using aligned latest observations.
    three = {s: float(x[0][-1] / max(x[0][-4], 1e-12) - 1.0) for s, x in market.items()}
    dispersion_now = float(np.std(list(three.values())))
    dispersion_hist = []
    for j in range(30, len(next(iter(market.values()))[0])):
        vals = [float(x[0][j] / max(x[0][j-3], 1e-12) - 1.0) for x in market.values() if len(x[0]) > j]
        if len(vals) >= 8: dispersion_hist.append(float(np.std(vals)))
    active_dispersion = len(dispersion_hist) >= 10 and dispersion_now > float(np.median(dispersion_hist[-60:]))
    med3 = float(np.mean(list(three.values())))
    for s, (c, h, l, r, _) in market.items():
        vol = max(float(np.std(r[-20:])), 0.008)
        relative[s] = -three[s]
        dispersion_relative[s] = -(three[s] - med3) if active_dispersion else np.nan
        clv[s] = float((2*c[-1] - h[-1] - l[-1]) / max(h[-1]-l[-1], 1e-12))
        five[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01))
        trend[s] = momentum[s]
        invvol[s] = 1.0 / vol
    med5 = float(np.median(list(five.values())))
    peer = {s: five[s] - med5 for s in five}
    factors = {
        "miner_3_20280113_relative_reversal_3d": rank(relative),
        "miner_3_20280127_dispersion_relative_reversal_3d": rank(dispersion_relative),
        "miner_3_clv_1d": rank(clv), "peer_median_leadlag_5d": rank(peer),
        "miner_2_risk_adjusted_momentum_20d": rank(momentum),
        "miner_2_20280127_volscaled_trend_10d": rank(trend),
    }
    score = {s: sum(FACTOR_WEIGHTS[k] * factors[k].get(s, 0.5) for k in FACTOR_WEIGHTS) for s in UNIVERSE}
    # Risk-off regime: defensive tradable benchmarks receive a modest tilt, with no cash sleeve.
    if "SPX" in market and market["SPX"][0][-1] < market["SPX"][0][-6] and market["SPX"][0][-1] < market["SPX"][0][-21]:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.10
        for s in ("BTC", "ETH", "WTI"): score[s] = max(0.05, score[s] - 0.06)
    mean_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(0.01, score[s]) * (0.80 + 0.20 * invvol.get(s, mean_iv) / max(mean_iv, 1e-12)) for s in UNIVERSE}
    weights = bounded(raw)
    vals = np.array([score[s] for s in UNIVERSE], dtype=float)
    scale = max(float(np.std(vals)), 1e-12)
    forecast_returns = {s: float(0.01 * (score[s] - float(np.mean(vals))) / scale) for s in UNIVERSE}
    try:
        data = json.loads((Path(__file__).parent / "factors/factor_ensemble.json").read_text())
        factor_ids = [str(x["factor_id"]) for x in data.get("selected_factors", [])[:10]]
    except Exception:
        factor_ids = list(FACTOR_WEIGHTS)
    rebalance_to_weights(weights, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
    last_date = decision
"}

