{"read_file": "import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def rank(x):
    out = {a: .5 for a in ASSETS}
    q = sorted((a, v) for a, v in x.items() if np.isfinite(v))
    if q:
        for i, (a, _) in enumerate(q):
            out[a] = (i + 1) / len(q)
    return out


def is_stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 62 and v[-1] > np.median(v[-61:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f.get("weight", 0)) for f in fs) - 1) > 1e-5:
        return
    data = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=270)
        if d is None or len(d) < 130:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(c) >= 100 and np.all(np.isfinite(c)) and np.all(c > 0):
            data[a] = c[-200:]
    if len(data) < 12:
        return
    n = min(map(len, data.values()))
    data = {a: c[-n:] for a, c in data.items()}
    ret = {a: np.diff(c) / c[:-1] for a, c in data.items()}
    med10 = float(np.median([np.mean(r[-10:]) for r in ret.values()]))
    breadth = float(np.mean([np.mean(r[-10:]) > 0 for r in ret.values()]))
    raw = {a: {} for a in data}
    for a, c in data.items():
        r = ret[a]
        v20 = max(float(np.std(r[-20:], ddof=1)), .008)
        v30 = max(float(np.std(r[-30:], ddof=1)), .008)
        v60 = max(float(np.std(r[-60:], ddof=1)), .008)
        r20, r60 = c[-1] / c[-21] - 1, c[-1] / c[-61] - 1
        path = max(float(np.sum(np.abs(r[-60:]))), 1e-12)
        dd = np.maximum.accumulate(c[-61:]) - c[-61:]
        raw[a] = {
            "riskadjusted_momentum": r60 / v60,
            "compressed_trend_reversal": -r60 / v60 * np.clip(v60 / v20, .5, 2),
            "efficiency_reversal": -(r60 / path) / v20,
            "relative_strength_reversal": -(r20 - 2 * med10) / v20,
            "breadth_gated_contrarian": (-(np.mean(r[-10:]) - med10) / v20) if breadth < .60 else 0,
            "drawdown_duration_reversal": -float(np.sum(dd > 0)) * (dd[-1] / max(c[-1], 1e-12)) / v20,
            "downside_stability_reversal": -float(np.std(np.minimum(r[-60:], 0), ddof=1)) / v60,
            "volatility_dispersion": -(v30 / v60 - 1),
        }
    aliases = {
        "riskadjusted_momentum": "riskadjusted_momentum",
        "compressed_trend_reversal": "compressed_trend_reversal",
        "efficiency_reversal": "efficiency_reversal",
        "relative_strength_reversal_volscaled": "relative_strength_reversal",
        "breadth_gated_contrarian": "breadth_gated_contrarian",
        "drawdown_duration_reversal": "drawdown_duration_reversal",
        "downside_stability_reversal": "downside_stability_reversal",
        "volatility_dispersion": "volatility_dispersion",
    }
    score = {a: 0.0 for a in ASSETS}
    ids = []
    for f in fs:
        fid = str(f.get("factor_id", ""))
        key = next((k for k in aliases if k in fid), None)
        if key is None:
            return
        ids.append(fid)
        rr = rank({a: raw[a][aliases[key]] for a in data})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    if is_stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06
    z = np.array([score[a] for a in ASSETS], float)
    z = (z - z.mean()) / max(float(z.std()), 1e-9)
    w = np.maximum(np.exp(.07 * np.clip(z, -.30, .30)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
"}

