python - <<'PY'
import glob,json,os
for f in glob.glob('factors/*.json'):
 if f.endswith('.bak') or f.endswith('factor_ensemble.json'): continue
 try:
  d=json.load(open(f)); m=d.get('validation_metrics',d.get('metrics',{}))
  print(os.path.basename(f), 'IC',m.get('ic_60d',m.get('IC_60D',m.get('ic'))),'ICIR',m.get('icir_60d',m.get('ICIR_60D',m.get('icir'))), 'status',d.get('status'))
 except Exception as e: print('ERR',f,e)
PY

